'use strict';
const FOOD_BRAND_UI8={bakeryView,bind};
function foodBrandPanel8(){const s=state.stores.find(s=>s.id===foodStore5),recipe=state.bakery5.recipes.find(r=>r.id===selectedFoodRecipe5),p=recipe?foodProduct8(recipe.id):null,combo=s?foodComboPolicy8(s.id):null,result=state.foodBrand8.history.at(-1)?.stores.find(x=>x.id===s?.id);return `<section class="card" style="margin-top:24px"><div class="card-head"><h2>Snídaně a obědy s kávou</h2>${s?'<button class="primary" id="foodCombosEdit8">Upravit kombinace</button>':''}</div><p class="sub">Snídaně do 11 hodin: káva a pečivo nebo dezert. Oběd 11–15 hodin: káva a sendvič. Kombinace používá skutečně obslouženého hosta a dostupné jídlo; káva se neprodává ani neúčtuje podruhé.</p>${s?rows([['Orientační snídaně s průměrným nápojem',money(menuSummary(s).price+s.menu.pastry.price-(combo.breakfast.enabled?combo.breakfast.discount:0))],['Orientační oběd s průměrným nápojem',money(menuSummary(s).price+s.menu.sandwich.price-(combo.lunch.enabled?combo.lunch.discount:0))],['Snídaně',combo.breakfast.enabled?'Aktivní · zvýhodnění '+money(combo.breakfast.discount):'Vypnutá'],['Oběd',combo.lunch.enabled?'Aktivní · zvýhodnění '+money(combo.lunch.discount):'Vypnutý'],['Poslední skutečný prodej kombinací',result?result.combos+' ks · zvýhodnění '+money(result.discount):'Čeká na odehraný týden']]):'<p class="empty">Otevři vlastní kavárnu a zapni fyzické jídlo.</p>'}</section><section class="card" style="margin-top:24px"><div class="card-head"><h2>Vlastní potravinová značka a obaly</h2>${recipe?'<button class="primary" id="foodBrandEdit8">Navrhnout identitu výrobku</button>':''}</div><p class="sub">Použije vybranou recepturu v sekci receptur. Design stojí 2 500 Kč. Obal se platí teprve při fyzické výrobě; název, barva a kolekce zůstanou uložené na již vyrobené šarži.</p>${p?`<div class="food-plan-card5" style="border-left:5px solid ${p.color}"><span class="eyelabel">${esc(p.brandName)}</span><h3>${esc(p.name)}</h3><p class="sub">${esc(p.collection||'Celoroční kolekce')} · ${FOOD_PACKS8[p.pack].name}</p></div>`:''}${recipe?rows([['Receptura',esc(recipe.name)],['Výrobek / značka',p?esc(p.name)+' / '+esc(p.brandName):'Zatím bez vlastní etikety'],['Obal',p?FOOD_PACKS8[p.pack].name+' · '+money(FOOD_PACKS8[p.pack].cost)+'/ks':'Základní dodávka'],['Sezónní kolekce',p?.start?'T'+p.start+'–'+p.end+' · '+esc(p.collection):'Celoroční výroba']]):''}<p class="sub">Mimo období kolekce nevzniká nová výroba. Dříve dodané, stále čerstvé zásoby se mohou doprodat. Sortiment kavárenské značky omezuje skutečnou výrobu i prodej receptur.</p>${s?.food5.lots.some(l=>l.label8)?`<details><summary>Etikety skutečných zásob</summary>${s.food5.lots.filter(l=>l.label8).map(l=>`<p class="sub">${esc(l.label8.name)} · ${esc(l.label8.brand)} · ${FOOD_PACKS8[l.label8.pack].name} · ${l.qty} ks · ${money(l.cost)}/ks</p>`).join('')}</details>`:''}${s?'<button class="soft" id="foodAssortmentEdit8">Sortiment této kavárenské značky</button>':''}</section>`;}
bakeryView=function(){return FOOD_BRAND_UI8.bakeryView()+foodBrandPanel8();};
function foodCombosDialog8(){const s=state.stores.find(s=>s.id===foodStore5),p=foodComboPolicy8(s.id),mix=districtMix6(s.id);show(`<h2>Kombinace · ${esc(loc(s.id).name)}</h2><p class="sub">Okolí: ${number((mix[GUEST_KEYS5.indexOf('office')]||0)*100,0)} % kancelářských hostů a ${number((mix[GUEST_KEYS5.indexOf('tourist')]||0)*100,0)} % turistů. Kanceláře mají silnější obědový zájem; snídaňové pečivo využívají i turisté. Sleva se odečítá z jídla, běžný kávový nákup již patří do skutečné tržby.</p>${['breakfast','lunch'].map((k,i)=>`<h3>${i?'Oběd · sendvič + káva':'Snídaně · pečivo/dezert + káva'}</h3><label class="checkbox-line"><input id="comboEnabled-${k}8" type="checkbox" ${p[k].enabled?'checked':''}> Nabízet</label>${field('Zvýhodnění kombinace / Kč',input('comboDiscount-'+k+'8',p[k].discount,5,40))}`).join('')}<p class="sub">Použije vybrané skutečné receptury denního odběru. Potřebuje zapnuté fyzické jídlo, příslušné vybavení, aktivní menu a čerstvé zásoby. Dodatečné jídlo zatíží i kapacitu obsluhy.</p><button class="primary" id="foodCombosSave8">Uložit nabídku</button>`);el('foodCombosSave8').onclick=()=>{try{setFoodCombos8(s.id,Object.fromEntries(['breakfast','lunch'].map(k=>[k,{enabled:el('comboEnabled-'+k+'8').checked,discount:Number(el('comboDiscount-'+k+'8').value)}])));persist();render();el('modal').close();}catch(e){toast(e.message);}};}
function foodBrandDialog8(){const recipe=state.bakery5.recipes.find(r=>r.id===selectedFoodRecipe5),p=foodProduct8(recipe.id)||{name:recipe.name,brandName:'Moje pekárna',pack:'paper',color:'#8a593c',collection:'',start:0,end:0};show(`<h2>Vlastní výrobek · ${esc(recipe.name)}</h2><div class="fields">${field('Název výrobku',`<input id="foodBrandName8" maxlength="50" value="${esc(p.name)}">`)}${field('Potravinová značka',`<input id="foodBrandCompany8" maxlength="40" value="${esc(p.brandName)}">`)}${field('Obal',`<select id="foodBrandPack8">${Object.entries(FOOD_PACKS8).map(([k,v])=>option(k,v.name+' · '+money(v.cost)+'/kus',p.pack)).join('')}</select>`)}${field('Barva etikety',`<input id="foodBrandColor8" type="color" value="${p.color}">`)}${field('Kolekce',`<input id="foodBrandCollection8" maxlength="50" value="${esc(p.collection)}">`)}${field('První týden kolekce · 0 celoročně',input('foodBrandStart8',p.start,0,100000))}${field('Poslední týden kolekce · 0 celoročně',input('foodBrandEnd8',p.end,0,100000))}</div><p class="sub">Design 2 500 Kč. Obal podle počtu skutečných kusů; u externího dodavatele patří do jeho kalkulace s obchodní přirážkou. Staré šarže si nechají svůj obal, název a náklad.</p><button class="primary" id="foodBrandPreview8">Prověřit návrh</button>`);el('foodBrandPreview8').onclick=()=>{try{const data={name:el('foodBrandName8').value,brandName:el('foodBrandCompany8').value,pack:el('foodBrandPack8').value,color:el('foodBrandColor8').value,collection:el('foodBrandCollection8').value,start:Number(el('foodBrandStart8').value),end:Number(el('foodBrandEnd8').value)},q=foodProductQuote8(recipe.id,data);confirmAction('Vytvořit identitu výrobku?',esc(data.name)+' / '+esc(data.brandName)+' · '+money(q.cost)+' nyní. Obal dalších kusů '+money(FOOD_PACKS8[data.pack].cost)+'/kus ve vlastní výrobě.',()=>brandFoodProduct8(recipe.id,data,q),'Zaplatit design');}catch(e){toast(e.message);}};}
function foodAssortmentDialog8(){const s=state.stores.find(s=>s.id===foodStore5),p=state.foodBrand8.assortments.find(p=>p.brand===s.brand);show(`<h2>Sortiment · ${esc(brand(s.brand).name)}</h2><p class="sub">Pravidlo sdílí všechny kavárny této značky. Nepovolená receptura se nenakoupí ani neprodá; před omezením zvaž zbývající zásoby a jejich trvanlivost. Bez pravidla jsou povolené všechny receptury.</p>${state.bakery5.recipes.map(r=>`<label class="checkbox-line"><input type="checkbox" data-food-assortment8="${r.id}" ${!p||p.recipes.includes(r.id)?'checked':''}> ${esc(foodProduct8(r.id)?.name||r.name)}</label>`).join('')}<div class="actions"><button class="primary" id="foodAssortmentSave8">Uložit sortiment značky</button><button class="soft" id="foodAssortmentClear8">Povolit všechny receptury</button></div>`);el('foodAssortmentSave8').onclick=()=>{try{setFoodAssortment8(s.brand,[...document.querySelectorAll('[data-food-assortment8]:checked')].map(x=>x.dataset.foodAssortment8));persist();render();el('modal').close();}catch(e){toast(e.message);}};el('foodAssortmentClear8').onclick=()=>{clearFoodAssortment8(s.brand);persist();render();el('modal').close();};}
bind=function(){FOOD_BRAND_UI8.bind();if(el('foodCombosEdit8'))el('foodCombosEdit8').onclick=foodCombosDialog8;if(el('foodBrandEdit8'))el('foodBrandEdit8').onclick=foodBrandDialog8;if(el('foodAssortmentEdit8'))el('foodAssortmentEdit8').onclick=foodAssortmentDialog8;};render();
